101	/**
102	 * One HTTP request with a raw path (sent as given, nothing normalised).
103	 * Resolves to { status, headers, text, json } (json is undefined when the body is not JSON).
104	 */
105	export function request(port, { method = 'GET', path = '/', headers = {}, body } = {}) {
106	  return new Promise((resolve, reject) => {
107	    const req = httpRequest(
108	      { host: '127.0.0.1', port, method, path, headers, agent: false },
109	      (res) => {
110	        const chunks = [];
111	        res.on('data', (c) => chunks.push(c));
112	        res.on('end', () => {
113	          const text = Buffer.concat(chunks).toString('utf8');
114	          let json;
115	          try {
116	            json = JSON.parse(text);
117	          } catch {
118	            json = undefined;
119	          }
120	          resolve({ status: res.statusCode, headers: res.headers, text, json });
121	        });
122	        res.on('error', reject);
123	      },
124	    );
125	    req.on('error', reject);
126	    req.end(body);
127	  });
128	}
129	
130	/** POST /api/bookings with a JSON body (object, or a raw string/Buffer). */
131	export function postBooking(port, value, headers = JSON_HEADERS) {
132	  const body = typeof value === 'string' || Buffer.isBuffer(value) ? value : JSON.stringify(value);
133	  return request(port, { method: 'POST', path: '/api/bookings', headers, body });
134	}
135	
136	export const getBookings = async (port, query = '') =>
137	  (await request(port, { path: `/api/bookings${query}` })).json.bookings;
138	
139	/**
140	 * Writes raw bytes to a socket and resolves to everything the server sent back
141	 * once it closes the connection (send `Connection: close`).
142	 */
143	export function rawRequest(port, data) {
144	  return new Promise((resolve, reject) => {
145	    const socket = connect(port, '127.0.0.1');
146	    const chunks = [];
147	    socket.on('data', (c) => chunks.push(c));
148	    socket.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
149	    socket.on('error', reject);
150	    socket.write(data);
151	  });
152	}
153	
154	/** Opens a socket and returns it plus a getter for the bytes received so far. */
155	export function openSocket(port) {
156	  return new Promise((resolve, reject) => {
157	    const socket = connect(port, '127.0.0.1', () => resolve({ socket, received: () => text }));
158	    let text = '';
159	    socket.setEncoding('utf8');
160	    socket.on('data', (d) => (text += d));
161	    socket.on('error', reject);
162	  });
163	}
164	
165	/** Resolves true when 127.0.0.1:<port> can be bound right now. */
166	export function isPortFree(port) {
167	  return new Promise((resolve) => {
168	    const probe = createNetServer();
169	    probe.once('error', () => resolve(false));
170	    probe.listen(port, '127.0.0.1', () => probe.close(() => resolve(true)));
171	  });
172	}
173	
174	/** Binds a port (0 = any) on 127.0.0.1 and returns { port, close() }. */
175	export function occupyPort(port = 0) {
176	  return new Promise((resolve, reject) => {
177	    const blocker = createNetServer();
178	    blocker.once('error', reject);
179	    blocker.listen(port, '127.0.0.1', () =>
180	      resolve({
181	        port: blocker.address().port,
182	        close: () => new Promise((done) => blocker.close(() => done())),
183	      }),
184	    );
185	  });
186	}
187	
188	export const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
